import { BaseRpcContext } from './base-rpc.context.js';
/**
 * @publicApi
 */
export class TcpContext extends BaseRpcContext {
    constructor(args) {
        super(args);
    }
    /**
     * Returns the underlying JSON socket.
     */
    getSocketRef() {
        return this.args[0];
    }
    /**
     * Returns the name of the pattern.
     */
    getPattern() {
        return this.args[1];
    }
}
